import itertools

def count_7s_in_multiples(limit, multiples_of):
    """
    Counts the occurrences of the digit '7' in numbers that are multiples 
    of any number in 'multiples_of', up to 'limit'.
    """

    # 1. Define the predicate: Check if a number is a multiple of any in the list
    def is_multiple(n):
        return any(n % m == 0 for m in multiples_of)

    # 2. Define the transformation: Count the digit '7' in the number
    def count_sevens(n):
        return str(n).count('7')

    # 3. Pipeline:
    #    - Generate numbers from 1 up to limit
    #    - Filter to keep only multiples
    #    - Map to convert numbers to their 7-count
    #    - Sum the results
    return sum(
        map(
            count_sevens,
            filter(
                is_multiple,
                itertools.count(1)  # Infinite stream starting at 1
            )
        )
    )

