def count_digits_seven(n):
    """
    Counts the total number of digit '7's in numbers less than n
    that are multiples of 11 or 13.
    """
    def count_sevens_in_number(num):
        count = 0
        while num > 0:
            if num % 10 == 7:
                count += 1
            num //= 10
        return count

    def is_multiple_of_11_or_13(num):
        return num % 11 == 0 or num % 13 == 0

    return sum(
        count_sevens_in_number(x)
        for x in range(1, n)
        if is_multiple_of_11_or_13(x)
