def round_away_from_zero(value: str) -> int:
    """
    Convert a string to float and round to the nearest integer,
    rounding 0.5 cases away from zero.
    """
    try:
        num = float(value)
        # For positive numbers, round 0.5 up; for negative, round 0.5 down
        if num >= 0:
            return int(num + 0.5)
        else:
            return int(num - 0.5)
    except ValueError:
        raise ValueError("Input must be a string representing a valid number.")

