def collatz_odd_numbers(n: int) -> list[int]:
    """
    Generates the odd numbers in a Collatz sequence for n,
    appends 1, and returns the sorted list.
    """
    if n < 1:
        return [1]

    def generate_odd_sequence(current: int):
        yield current
        while current != 1:
            if current % 2 == 0:
                current //= 2
            else:
                current = 3 * current + 1
                yield current

    # Functional pipeline: map, filter, unique, sort
    return sorted(
        list(
            dict.fromkeys(
                filter(
                    lambda x: x % 2 != 0,
                    generate_odd_sequence(n)
                )
            )
        )
    )
